// Detections D1-D4 over Roster's own replay and grade records (DESIGN.md §"Observability (neatlogs)").
//
// These flag Roster's own silent mistakes: a pass the visible suite believed, a setup whose diff we
// could not attribute, a run that cost far more than the incumbent, and an environment flake that
// follows a task across setups. Every detection is derived from records we already hold, so the
// module is pure: same input, same output.
import { FailureCode } from "../types.ts";

/** One replay outcome as the detections see it. Mirrors the fields the replay/grade records carry. */
export interface ReplayRecord {
  task: string;
  setup: string;
  /** The visible suite passed. */
  suitePass: boolean;
  /** The hidden acceptance tests passed. */
  hiddenPass: boolean;
  /** The scope guard passed. */
  scopeOk: boolean;
  /** Cost in USD, or null when the record has no cost. Nulls are ignored, never guessed. */
  costUsd: number | null;
  failureCodes: string[];
}

export interface DetectionInput {
  replays: ReplayRecord[];
  /** The setup currently in place; D3 measures every cost against its median. */
  incumbent: string;
  /** Per setup, the share (0..1) of changed lines the attribution step could not map. */
  unmappedLineShare: Record<string, number>;
}

export interface Detection {
  id: "D1" | "D2" | "D3" | "D4";
  setup?: string;
  task?: string;
  detail: string;
}

/** D2 fires above this share of unmapped lines. */
export const UNMAPPED_SHARE_THRESHOLD = 0.3;
/** D3 fires above this multiple of the incumbent median cost. */
export const COST_MULTIPLIER = 3;

/**
 * The lower median: with an even count, the lower of the two middle values, never their average.
 *
 * The averaging median would let a cost anomaly on the incumbent hide itself. Against incumbent
 * costs of [10, 20, 30, 70] the average is 25, so the threshold becomes 75 and the 70 replay that
 * should be flagged falls under it. The lower median stays at 20 and the outlier is caught.
 */
function lowerMedian(values: number[]): number | null {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor((sorted.length - 1) / 2)]!;
}

/** D1: the visible suite passed, but hidden acceptance or the scope guard failed. */
function detectD1(replays: ReplayRecord[]): Detection[] {
  const out: Detection[] = [];
  for (const r of replays) {
    if (!r.suitePass) continue;
    if (r.hiddenPass && r.scopeOk) continue;
    const missed: string[] = [];
    if (!r.hiddenPass) missed.push("hidden acceptance");
    if (!r.scopeOk) missed.push("the scope guard");
    out.push({
      id: "D1",
      setup: r.setup,
      task: r.task,
      detail: `visible suite passed but ${missed.join(" and ")} failed`,
    });
  }
  return out;
}

/** D2: more than 30% of a setup's changed lines are unmapped. */
function detectD2(unmappedLineShare: Record<string, number>): Detection[] {
  const out: Detection[] = [];
  for (const [setup, share] of Object.entries(unmappedLineShare)) {
    if (!(share > UNMAPPED_SHARE_THRESHOLD)) continue;
    out.push({
      id: "D2",
      setup,
      detail: `unmapped line share ${share} exceeds ${UNMAPPED_SHARE_THRESHOLD}`,
    });
  }
  return out;
}

/** D3: a replay costs more than 3x the median incumbent cost. No incumbent costs -> no D3. */
function detectD3(replays: ReplayRecord[], incumbent: string): Detection[] {
  const baseline = lowerMedian(
    replays.filter((r) => r.setup === incumbent && r.costUsd !== null).map((r) => r.costUsd!),
  );
  if (baseline === null) return [];
  const threshold = COST_MULTIPLIER * baseline;
  const out: Detection[] = [];
  for (const r of replays) {
    if (r.costUsd === null || !(r.costUsd > threshold)) continue;
    out.push({
      id: "D3",
      setup: r.setup,
      task: r.task,
      detail: `cost $${r.costUsd} exceeds ${COST_MULTIPLIER}x the incumbent "${incumbent}" median ($${baseline}, threshold $${threshold})`,
    });
  }
  return out;
}

/** D4: F6 hits the same task across at least two distinct setups. One detection per task. */
function detectD4(replays: ReplayRecord[]): Detection[] {
  const setupsByTask = new Map<string, Set<string>>();
  for (const r of replays) {
    if (!r.failureCodes.includes(FailureCode.F6)) continue;
    let setups = setupsByTask.get(r.task);
    if (!setups) setupsByTask.set(r.task, (setups = new Set()));
    setups.add(r.setup);
  }
  const out: Detection[] = [];
  for (const [task, setups] of setupsByTask) {
    if (setups.size < 2) continue;
    // No single setup owns the flake, so the detection is keyed by task alone.
    const names = [...setups].sort();
    out.push({
      id: "D4",
      task,
      detail: `F6 hit task "${task}" on ${names.length} distinct setups (${names.join(", ")})`,
    });
  }
  return out;
}

/**
 * Flags Roster's own silent mistakes from replay and grade records.
 *
 * Output is sorted by id, then setup, then task. D4 entries carry no setup (the flake spans
 * setups), so they compare as the empty setup and order among themselves by task.
 */
export function detect(input: DetectionInput): Detection[] {
  const { replays, incumbent, unmappedLineShare } = input;
  const detections = [
    ...detectD1(replays),
    ...detectD2(unmappedLineShare),
    ...detectD3(replays, incumbent),
    ...detectD4(replays),
  ];
  return detections.sort((a, b) => {
    if (a.id !== b.id) return a.id < b.id ? -1 : 1;
    const as = a.setup ?? "";
    const bs = b.setup ?? "";
    if (as !== bs) return as < bs ? -1 : 1;
    const at = a.task ?? "";
    const bt = b.task ?? "";
    return at < bt ? -1 : at > bt ? 1 : 0;
  });
}

