import { describe, expect, test } from "bun:test";
import { COST_MULTIPLIER, UNMAPPED_SHARE_THRESHOLD, detect, type DetectionInput, type ReplayRecord } from "../src/obs/detections.ts";

function replay(over: Partial<ReplayRecord> & { task: string; setup: string }): ReplayRecord {
  return { suitePass: false, hiddenPass: true, scopeOk: true, costUsd: null, failureCodes: [], ...over };
}

/** The id/setup/task triple of each detection, with unset fields omitted. */
function summarize(results: ReturnType<typeof detect>) {
  return results.map((r) => {
    const out: { id: string; setup?: string; task?: string } = { id: r.id };
    if (r.setup !== undefined) out.setup = r.setup;
    if (r.task !== undefined) out.task = r.task;
    return out;
  });
}

describe("detect D1 silent pass", () => {
  test("fires when the visible suite passed but hidden acceptance or the scope guard failed", () => {
    const input: DetectionInput = {
      replays: [
        replay({ task: "t1", setup: "s1", suitePass: true, hiddenPass: false }),
        replay({ task: "t2", setup: "s1", suitePass: true, scopeOk: false }),
        replay({ task: "t3", setup: "s2", suitePass: true, hiddenPass: false, scopeOk: false }),
        replay({ task: "t4", setup: "s1", suitePass: true }),
        replay({ task: "t5", setup: "s1", suitePass: false, hiddenPass: false, scopeOk: false }),
      ],
      incumbent: "s1",
      unmappedLineShare: { s1: 0, s2: 0 },
    };

    const result = detect(input);

    expect(summarize(result)).toEqual([
      { id: "D1", setup: "s1", task: "t1" },
      { id: "D1", setup: "s1", task: "t2" },
      { id: "D1", setup: "s2", task: "t3" },
    ]);
    for (const d of result) expect(typeof d.detail).toBe("string");
  });

  test("names the checks that failed in the detail", () => {
    const input: DetectionInput = {
      replays: [replay({ task: "t1", setup: "s1", suitePass: true, hiddenPass: false })],
      incumbent: "s1",
      unmappedLineShare: {},
    };

    const [d] = detect(input);

    expect(d!.detail).toContain("hidden acceptance");
    expect(d!.detail).not.toContain("scope guard");
  });

  test("does not fire on a clean pass", () => {
    const input: DetectionInput = {
      replays: [replay({ task: "t1", setup: "s1", suitePass: true })],
      incumbent: "s1",
      unmappedLineShare: {},
    };

    expect(detect(input)).toEqual([]);
  });
});

describe("detect D2 unmapped line share", () => {
  test("fires strictly above the threshold", () => {
    const input: DetectionInput = {
      replays: [],
      incumbent: "inc",
      unmappedLineShare: { a: 0.31, b: 0.3, c: 0.3000001, d: 0.0, e: 0.301 },
    };

    const result = detect(input);

    expect(result.every((d) => d.id === "D2")).toBe(true);
    expect(summarize(result)).toEqual([
      { id: "D2", setup: "a" },
      { id: "D2", setup: "c" },
      { id: "D2", setup: "e" },
    ]);
    for (const d of result) expect(typeof d.detail).toBe("string");
  });

  test("fires only above the threshold, never at it", () => {
    expect(UNMAPPED_SHARE_THRESHOLD).toBe(0.3);

    const atThreshold = detect({ replays: [], incumbent: "inc", unmappedLineShare: { s: UNMAPPED_SHARE_THRESHOLD } });
    const above = detect({ replays: [], incumbent: "inc", unmappedLineShare: { s: 1 } });

    expect(atThreshold).toEqual([]);
    expect(above.map((d) => d.setup)).toEqual(["s"]);
  });

  test("a setup absent from the map is never flagged", () => {
    const result = detect({ replays: [], incumbent: "inc", unmappedLineShare: {} });

    expect(result).toEqual([]);
  });
});

describe("detect D3 cost anomaly", () => {
  test("fires above 3x the incumbent median and ignores null costs", () => {
    const input: DetectionInput = {
      replays: [
        replay({ task: "base1", setup: "inc", costUsd: 10 }),
        replay({ task: "base2", setup: "inc", costUsd: 20 }),
        replay({ task: "base3", setup: "inc", costUsd: 30 }),
        replay({ task: "base_null", setup: "inc", costUsd: null }),
        replay({ task: "high1", setup: "s1", costUsd: 61 }),
        replay({ task: "exact", setup: "s1", costUsd: 60 }),
        replay({ task: "high_inc", setup: "inc", costUsd: 70 }),
        replay({ task: "high2", setup: "s2", costUsd: 100 }),
        replay({ task: "null_cost", setup: "s3", costUsd: null }),
      ],
      incumbent: "inc",
      unmappedLineShare: { inc: 0, s1: 0, s2: 0, s3: 0 },
    };

    const result = detect(input);

    expect(result.every((d) => d.id === "D3")).toBe(true);
    expect(summarize(result)).toEqual([
      { id: "D3", setup: "inc", task: "high_inc" },
      { id: "D3", setup: "s1", task: "high1" },
      { id: "D3", setup: "s2", task: "high2" },
    ]);
  });

  test("uses the lower middle value so an incumbent outlier cannot mask itself", () => {
    // Median of [10, 20, 30, 70] averaged would be 25, lifting the threshold to 75 and sparing the 70.
    const result = detect({
      replays: [replay({ task: "a", setup: "inc", costUsd: 10 }), replay({ task: "b", setup: "inc", costUsd: 20 }), replay({ task: "c", setup: "inc", costUsd: 30 }), replay({ task: "outlier", setup: "inc", costUsd: 70 })],
      incumbent: "inc",
      unmappedLineShare: {},
    });

    expect(summarize(result)).toEqual([{ id: "D3", setup: "inc", task: "outlier" }]);
  });

  test("emits no D3 when the incumbent has no cost values", () => {
    const result = detect({
      replays: [replay({ task: "t1", setup: "s1", costUsd: 1000 }), replay({ task: "t2", setup: "inc", costUsd: null })],
      incumbent: "inc",
      unmappedLineShare: { s1: 0, inc: 0 },
    });

    expect(result).toEqual([]);
  });

  test("emits no D3 when there is no incumbent replay at all", () => {
    const result = detect({
      replays: [replay({ task: "t1", setup: "s1", costUsd: 1000 })],
      incumbent: "inc",
      unmappedLineShare: {},
    });

    expect(result).toEqual([]);
  });

  test("fires a single-replay incumbent at 3x its own cost", () => {
    expect(COST_MULTIPLIER).toBe(3);

    const result = detect({
      replays: [replay({ task: "base", setup: "inc", costUsd: 2 }), replay({ task: "high", setup: "s1", costUsd: 6.01 })],
      incumbent: "inc",
      unmappedLineShare: {},
    });

    expect(summarize(result)).toEqual([{ id: "D3", setup: "s1", task: "high" }]);
  });
});

describe("detect D4 environment flake", () => {
  test("fires once per task when F6 hits two or more distinct setups", () => {
    const input: DetectionInput = {
      replays: [
        replay({ task: "taskA", setup: "s1", failureCodes: ["F6"] }),
        replay({ task: "taskA", setup: "s2", failureCodes: ["F6"] }),
        replay({ task: "taskA", setup: "s1", failureCodes: ["F6"] }),
        replay({ task: "taskB", setup: "x", failureCodes: ["F6"] }),
        replay({ task: "taskB", setup: "y", failureCodes: ["F6"] }),
        replay({ task: "taskB", setup: "z", failureCodes: ["F6"] }),
        replay({ task: "taskC", setup: "s1", failureCodes: ["F6"] }),
        replay({ task: "taskD", setup: "s1", failureCodes: ["F1"] }),
        replay({ task: "taskE", setup: "s1", failureCodes: ["F6"] }),
        replay({ task: "taskE", setup: "s2", failureCodes: ["F1"] }),
      ],
      incumbent: "inc",
      unmappedLineShare: { s1: 0, s2: 0, x: 0, y: 0, z: 0, inc: 0 },
    };

    const result = detect(input);

    expect(result.every((d) => d.id === "D4")).toBe(true);
    expect(summarize(result)).toEqual([
      { id: "D4", task: "taskA" },
      { id: "D4", task: "taskB" },
    ]);
    for (const d of result) expect(typeof d.detail).toBe("string");
  });

  test("repeated F6 on one setup is not a flake", () => {
    const result = detect({
      replays: [replay({ task: "t1", setup: "s1", failureCodes: ["F6"] }), replay({ task: "t1", setup: "s1", failureCodes: ["F6"] })],
      incumbent: "inc",
      unmappedLineShare: {},
    });

    expect(result).toEqual([]);
  });

  test("an F6 alongside other codes still counts", () => {
    const result = detect({
      replays: [replay({ task: "t1", setup: "s1", failureCodes: ["F2", "F6"] }), replay({ task: "t1", setup: "s2", failureCodes: ["F6"] })],
      incumbent: "inc",
      unmappedLineShare: {},
    });

    expect(summarize(result)).toEqual([{ id: "D4", task: "t1" }]);
  });

  test("the setup field is absent, not empty, on a D4", () => {
    const [d] = detect({
      replays: [replay({ task: "t1", setup: "s1", failureCodes: ["F6"] }), replay({ task: "t1", setup: "s2", failureCodes: ["F6"] })],
      incumbent: "inc",
      unmappedLineShare: {},
    });

    expect(d!.setup).toBeUndefined();
  });
});

describe("detect output ordering", () => {
  test("sorts by id, then setup, then task", () => {
    const input: DetectionInput = {
      replays: [
        replay({ task: "d1_task_b", setup: "b", suitePass: true, hiddenPass: false }),
        replay({ task: "d1_task_a", setup: "a", suitePass: true, scopeOk: false }),
        replay({ task: "inc1", setup: "inc", costUsd: 10 }),
        replay({ task: "inc2", setup: "inc", costUsd: 20 }),
        replay({ task: "inc3", setup: "inc", costUsd: 30 }),
        replay({ task: "high", setup: "a", costUsd: 61 }),
        replay({ task: "m", setup: "s1", failureCodes: ["F6"] }),
        replay({ task: "m", setup: "s2", failureCodes: ["F6"] }),
      ],
      incumbent: "inc",
      unmappedLineShare: { z: 0.35, a: 0.31 },
    };

    const result = detect(input);

    expect(summarize(result)).toEqual([
      { id: "D1", setup: "a", task: "d1_task_a" },
      { id: "D1", setup: "b", task: "d1_task_b" },
      { id: "D2", setup: "a" },
      { id: "D2", setup: "z" },
      { id: "D3", setup: "a", task: "high" },
      { id: "D4", task: "m" },
    ]);
  });

  test("orders same-id, same-setup D1s by task", () => {
    const result = detect({
      replays: [replay({ task: "z", setup: "s", suitePass: true, hiddenPass: false }), replay({ task: "a", setup: "s", suitePass: true, hiddenPass: false })],
      incumbent: "inc",
      unmappedLineShare: {},
    });

    expect(result.map((d) => d.task)).toEqual(["a", "z"]);
  });

  test("is pure: the input is not mutated and a repeat call matches", () => {
    const input: DetectionInput = {
      replays: [replay({ task: "t", setup: "s", suitePass: true, hiddenPass: false })],
      incumbent: "inc",
      unmappedLineShare: { s: 0.4 },
    };
    const snapshot = JSON.stringify(input);

    const first = detect(input);
    const second = detect(input);

    expect(JSON.stringify(input)).toBe(snapshot);
    expect(second).toEqual(first);
  });
});

